/*
 * English for the Lamplit (Lamplit) UI.
 *
 * Keys are the Chinese source text exactly as it appears in the UI (whitespace
 * collapsed). {0}, {1}… stand for the parts a template fills in, in order;
 * those parts are translated too when they are themselves UI text.
 * index.html applies this dictionary when the language is English. Chat
 * content (messages, things you type, what bots write) is never translated.
 *
 * Adding UI text in Chinese? Add its English here (scripts/smoke.mjs checks
 * that every Chinese string in the UI has an entry).
 */
