  "把这一轮改过、删过的文件恢复成之前的样子（7 天内有效）": "Put the files this turn changed or deleted back as they were (within 7 days)",
  "没能撤销": "Couldn't undo",
  "撤销了一部分：{0}": "Partly undone: {0}",
  "已恢复成这一轮之前的样子": "Restored to how it was before this turn",
  "没能撤销：{0}": "Couldn't undo: {0}",
  "你好！用两三句话介绍一下你能帮我做什么。": "Hi! In two or three sentences, what can you do for me?",
  "选服务商": "Provider",
  "填密钥": "Key",
  "试一句": "Try it",
  "现在用的是内置演示，回答由脚本生成，不会真的理解你的话。选一家模型服务商，填上密钥，它就开始正经干活。": "This is the built-in demo: replies are scripted and don't really understand you. Pick a model provider and paste a key, and it starts doing real work.",
  "推荐：中文好、便宜，注册就能拿密钥": "Recommended: strong Chinese, cheap, a key right after sign-up",
  "默认模型 {0}": "Default model {0}",
  "其他服务商、自己的地址：去设置 → 模型": "Other providers or your own address: Settings → Model",
  "填上 {0} 的密钥": "Paste your {0} key",
  "在服务商的网站登录，新建一个 API Key，复制回来贴在下面。密钥只存在这台电脑上，加密保存。": "Sign in on the provider's site, create an API key and paste it below. The key stays on this computer, encrypted.",
  "去 {0} 拿密钥 ↗": "Get a key from {0} ↗",
  "连接并试一句": "Connect and try it",
  "保存密钥，测试连接，然后替你发第一句话…": "Testing the connection, saving the key, then sending your first message…",
  "← 换一家": "← Another provider",
  "先把密钥贴进来。": "Paste the key first.",
  "没连上：{0}。检查一下密钥有没有复制全，或者换一家试试。": "Couldn't connect: {0}. Check the key was copied in full, or try another provider.",
  "设置单独账户": "Set up a separate account",
  "已开启：机器人执行的命令用单独的 Windows 账户 lamplit-runner 来跑，看不到你的用户文件夹（C:\\Users\\你），包括 Lamplit 自己的数据（密钥、配对凭据、保险箱）；工作区和开放的文件夹照常可用，Python、ffmpeg 这类装在你用户文件夹里的工具可以运行。其他磁盘（比如 D 盘）按 Windows 默认，所有账户都能读写。命令跑在它自己的隐藏桌面上，看不到你的窗口、剪贴板和键盘；它打开的程序也不会出现在你的屏幕上。以管理员身份运行的命令、你批准越过边界的那一步，用你自己的账户。": "On: the bots' commands run as a separate Windows account, lamplit-runner, which cannot see your user folder (C:\\Users\\you), including Lamplit's own data (keys, pairing tokens, the vault). The workspace and opened folders work as usual, and tools installed in your user folder such as Python and ffmpeg can run. Other drives (such as D:) keep Windows' defaults: every account can read and write them. Commands run on a hidden desktop of their own: they cannot see your windows, clipboard or keyboard, and programs they open do not appear on your screen. Commands run as administrator, and steps you let past the boundary, use your own account.",
  "机器人的命令现在都不会运行：{0}。不会改用你的账户或你的桌面去跑。重启电脑通常就好了。": "The bots' commands will not run at the moment: {0}. They are never run as your account or on your desktop instead. Restarting the computer usually fixes it.",
  "给机器人单独开的桌面建不起来": "the bots' own desktop could not be set up",
  "正在设置：在弹出的管理员确认里点「是」…": "Setting up: click \"Yes\" in the administrator prompt…",
  "正在检查单独账户…": "Checking the separate account…",
  "还没有隔离：机器人执行的命令用你自己的账户来跑，看得到 Lamplit 自己的数据。点「设置单独账户」，Lamplit 会建一个隐藏的普通账户 lamplit-runner 来跑这些命令（会弹一次管理员确认）。{0}": "Not isolated yet: the bots' commands run as your own account and can see Lamplit's own data. Click \"Set up a separate account\" and Lamplit creates a hidden standard account, lamplit-runner, to run them (one administrator prompt). {0}",
  "上次没成功：{0}。": "Last attempt failed: {0}.",
  "没有生效：{0}。命令照常用你自己的账户运行。可以再点一次「设置单独账户」。": "Not working: {0}. Commands run as your own account as before. You can click \"Set up a separate account\" again.",
  "这台机器上机器人执行的命令没有隔离。": "The bots' commands are not isolated on this machine.",
  "没能开始设置：{0}": "Couldn't start the setup: {0}",
  "找不到配对码？": "Can't find the pairing code?",
  "配对码是 8 位数字，每天换一次。在已经连着这台机器的手机或浏览器上，打开 设置 → 手机和外网 就能看到。": "The pairing code is 8 digits and changes every day. On a phone or browser already connected to this machine, open Settings → Phone & away to see it.",
  "在这台机器上打开终端运行": "On this machine, open a terminal and run",
  "，结果里的 code 就是（Windows 上用 curl.exe）。": "; the code in the result is the one (use curl.exe on Windows).",
  "这台机器是 Lamplit 帮你装的：回到这台电脑，在 设置 → 机器 → 添加机器 里用同样的地址再连一次，会重新配对，已经装好的部分不会重做。": "If Lamplit installed this machine for you: go back to this computer and connect it again under Settings → Machines → Add machine with the same address. It pairs again and skips what is already installed.",
  "配对码不对。配对码每天换一次，看下面「找不到配对码？」。": "Wrong pairing code. It changes every day: see \"Can't find the pairing code?\" below.",
  "回不去这台电脑，重启 Lamplit 试试。": "Couldn't go back to this computer. Try restarting Lamplit.",
  "已复制": "Copied",
  "复制失败，请长按选择文字": "Copy failed; long-press to select the text",
  "先输入配对码。": "Enter the pairing code first.",
  "地址格式不对，例如 http://192.168.1.8:4390": "That address doesn't look right, e.g. http://192.168.1.8:4390",
  "正在前往": "Going to",
  "这个地址打不开，检查一下是不是同一局域网。": "Can't open this address. Check you're on the same network.",
  "连接中…": "Connecting…",
  "配对成功，正在进入…": "Paired. Opening…",
  "配对码不对，检查一下电脑上 Lamplit 的「设置 → 配对」。": "Wrong pairing code. Check Lamplit's Settings → Phone & away on the computer.",
  "试得太多次了，等一分钟再试。": "Too many attempts. Wait a minute and try again.",
  "服务端还没有配对接口（404）。如果你就在这台电脑上，可以直接刷新试试。": "The server has no pairing API (404). If you're on that computer, try reloading.",
  "配对失败，检查配对码是否过期。": "Pairing failed. Check whether the code has expired.",
  "连不上 Lamplit": "Can't reach Lamplit",
  "服务没有响应。": "The server isn't responding.",
  "重试": "Retry",
  "地址已复制": "Address copied",
  "配对码已复制": "Pairing code copied",
  "未生成": "Not generated",
  "服务端没有提供配对信息（/api/pairing 404）。在同一局域网里，可以用 {0} 打开；如果这台机器要求认证，请在服务端配置里生成配对码。": "The server provides no pairing info (/api/pairing 404). On the same network you can open {0}; if this machine requires auth, generate a pairing code in the server config.",
  "有地址但没有配对码：手机打开这个地址后会要求配对码，请在服务端生成。": "There's an address but no pairing code: the phone will ask for one; generate it on the server.",
  "需要配对（本机除外）": "Pairing required (except this computer)",
  "仅本机，无需配对": "This computer only, no pairing",

