  "第 {0}/{1} 步 · 已用 {2} · 还要约 {3} 分钟": "Step {0}/{1} · {2} elapsed · about {3} min left",
  "完成 · 用时 {0}": "Done · took {0}",
  "那台机器上的安装超过 {0} 分钟还没结束（多半是下载太慢），它会在后台继续装完。过几分钟再点一次「连接并自动配置」，会等它装完再接着做。": "Setup on that machine is still running after {0} minutes (most likely slow downloads); it will finish in the background. Press “Connect and set up” again in a few minutes and it will pick up from there.",
  "下载": "Download",
  "发到「{0}」· 输入 @ 指定谁来回答，不指定就由 {1} 先答…": "Message “{0}” · type @ to pick who answers; otherwise {1} answers first…",
  "所有人": "everyone",
  "每个成员都回答": "every member answers",
  "看 {0} 的屏幕": "Watch {0}’s screen",
  "连不上本机的 Lamplit 服务": "Can’t reach Lamplit on this computer",
  "上传桌面组件 TightVNC（{0} MB）…": "Uploading the desktop component TightVNC ({0} MB)…",
  "看图": "Image understanding",
  "聊天模型（如 DeepSeek）只能读文字。这里配一个看图模型，Bot 就能看懂你发的图片和它自己的截图。": "Chat models such as DeepSeek read text only. Add a vision model here so bots can understand the images you send and the screenshots they take.",
  "看图服务": "Vision service",
  "保存看图设置": "Save vision settings",
  "清除看图密钥": "Clear vision key",
  "还不能用：选一个看图服务并填密钥（硅基流动的密钥就行）。": "Not available yet: pick a vision service and enter its key (a SiliconFlow key works).",
  "已可用：{0}。": "Ready: {0}.",
  "已可用：沿用语音输入的硅基流动密钥，看图模型 {0}。": "Ready: uses the voice input SiliconFlow key, vision model {0}.",
  "已可用：沿用聊天模型的密钥，看图模型 {0}。": "Ready: uses the chat model key, vision model {0}.",
  "看图设置已保存（没同步到其他机器）": "Vision settings saved (not copied to other machines)",
  "看图设置已保存；没同步上：{0}": "Vision settings saved; not copied to: {0}",
  "看图设置已保存，并同步到所有机器": "Vision settings saved and copied to every machine",
  "看图密钥已清除": "Vision key cleared",
  "看图设置已保存": "Vision settings saved",
  "需要你接管屏幕": "Your turn on the screen",
  "完成这一步": "finish this step",
  "接管屏幕": "Take over the screen",
  "我弄好了，继续": "Done, continue",
  "密码、验证码只在屏幕上输入，不要发在聊天里。": "Type passwords and codes only on the screen, never in the chat.",
  "权限": "Permissions",
  "这台机器上，机器人做事前要不要先问你。每台机器单独设置。": "Whether bots ask you before acting on this machine. Each machine has its own setting.",
  "谨慎": "Careful",
  "删文件、执行命令、发消息、改设置等有影响的操作，每次都先问我（所有机器人一样）。": "Anything with an effect (deleting files, running commands, sending messages, changing settings) asks me first, for every bot.",
  "标准": "Standard",
  "高风险操作先问我；常规操作信任的机器人（如助理）可以直接做。": "High-risk actions ask me first; trusted bots (like the assistant) do routine actions on their own.",
  "放手": "Hands-off",
  "都让机器人自己做，只有危险命令还会问我。适合专门给机器人用的电脑。": "Bots do everything themselves; only dangerous commands still ask. For a computer dedicated to the bots.",
  "禁止的命令": "Blocked commands",
  "内置的危险命令始终会拦下：删除整个系统、格式化磁盘、关机、改密码、把桌面暴露到网络等。": "Built-in dangerous commands are always stopped: wiping the system, formatting disks, shutting down, changing passwords, exposing the desktop to the network, and so on.",
  "添加": "Add",
  "命令里出现这些词时，机器人会停下来问你（放手模式也一样）。": "When a command contains these words, the bot stops and asks you (even in hands-off mode).",
  "审批级别": "Approval level",
  "再加一条，比如 git push 或 docker rm": "Add one, e.g. git push or docker rm",
  "这是一台远程机器，默认「放手」：机器人可以装软件、用 sudo，不用逐条问你。": "This is a remote machine, hands-off by default: bots can install software and use sudo without asking each time.",
  "这台电脑上，机器人做事前要不要先问你。每台机器单独设置。": "Whether bots ask you before acting on this computer. Each machine has its own setting.",
  "已移除": "Removed",
  "已改为「{0}」": "Changed to “{0}”",
  "已添加：{0}": "Added: {0}",
  "它能做什么": "What it can do",
  "常规操作直接做，不用每次问我（「标准」级别下）": "Do routine actions without asking me each time (at the Standard level)",
  "运行命令、装软件": "run commands, install software",
  "读写文件": "Read and write files",
  "在工作区读、写、建文件夹": "read, write and create folders in the workspace",
  "上网和浏览器": "Web and browser",
  "打开网页、抓取内容": "open pages, fetch content",
  "记忆和技能": "Memory and skills",
  "记住你的习惯、保存做法": "remember your habits, save how-tos",
  "建机器人和群、派活": "Create bots and groups, hand off work",
  "改设置": "Change settings",
  "模型、主题等": "model, theme and so on",
  "我的规则": "My rules",
  "用一句话告诉机器人什么要先问你、什么可以直接做。按意思判断，不用写得很精确。": "Tell the bots in one sentence what to ask you about and what they can just do. Matched by meaning, so it needn’t be precise.",
  "先问我": "Ask me first",
  "直接做": "Just do it",
  "规则冲突时「先问我」优先；内置的危险命令拦截和机器人的能力限制始终有效。": "When rules conflict, “ask me first” wins; the built-in danger list and each bot’s abilities always apply.",
  "比如：发邮件先问我 / 装软件直接做 / 不许动 D 盘": "e.g. ask before sending email / installing software is fine / never touch drive D",
  "还没有规则。": "No rules yet.",
  "已添加规则：{0}": "Rule added: {0}",
  "能看能控": "View and control",
  "看得到这台机器的屏幕，也能用鼠标键盘操作（登录、付款时要用）。": "See this machine’s screen and use its mouse and keyboard (needed for logins and payments).",
  "只能看": "View only",
  "只看画面，鼠标键盘不会传过去，防止误点。这是防误操作，不是安全隔离：已配对的设备随时可以改回来。": "Only see the screen; mouse and keyboard are not sent, so nothing gets clicked by accident. This guards against mistakes, it is not a security boundary: any paired device can switch it back.",
  "这台机器的接管设成了「只能看」：要操作的话，先在 设置 → 审批 里改成「能看能控」。": "Takeover on this machine is set to “view only”: to use the screen, switch it to “view and control” under Settings → Approval.",
  "接管桌面改为「只能看」": "Takeover set to “view only”",
  "接管桌面改为「能看能控」": "Takeover set to “view and control”",
  "操作记录": "Activity log",
  "这台机器上，机器人做过哪些有影响的事、谁批准的、谁接管过桌面、权限怎么改过。": "What the bots did on this machine that had an effect, who approved it, who took over the desktop, and how permissions changed.",
