  "保险箱": "Vault",
  "网站的账号密码存在这里，机器人登录时直接从这里填，聊天里不出现，机器人自己也看不到。每台机器有自己的保险箱。": "Website logins live here. Bots fill them in straight from the vault: they never appear in the chat, and the bots themselves never see them. Each machine has its own vault.",
  "内容加密保存在这台机器上：单独拷走文件也打不开；但能完全控制这台机器的人仍然能取出来。": "Contents are encrypted on this machine: a copied file alone cannot be opened, but someone in full control of this machine can still get them out.",
  "添加一条": "Add an entry",
