  "同时发到飞书": "Also send to Feishu",
  "助理会汇总过去 24 小时所有机器上的情况：要你处理的事、每个机器人做完了什么、新做的页面。": "The assistant sums up the last 24 hours on all your machines: what needs you, what each bot finished, new pages.",
