  "Tailscale 没装：密钥没能交给那台机器（{0}）": "Tailscale not installed: the key did not reach that machine ({0})",
  "Tailscale 正在后台安装并加入你的网络，几分钟后这台机器会出现 100 开头的地址": "Tailscale is installing in the background and joining your network; in a few minutes this machine gets an address starting with 100",
  "Tailscale 没装：安装脚本没有收到密钥": "Tailscale not installed: the setup script did not get the key",
  "这是 API 访问令牌（tskey-api-），不能用来加设备：在 Tailscale 后台 Settings → Keys 里点「Generate auth key」，用 tskey-auth- 开头的那种。": "That is an API access token (tskey-api-), which cannot add a device: in the Tailscale admin console under Settings → Keys, click \"Generate auth key\" and use the tskey-auth- kind.",
  "这是 Tailscale 的 API 访问令牌（tskey-api-），不能用来加设备：在 Tailscale 后台 Settings → Keys 里点「Generate auth key」，用 tskey-auth- 开头的那种。": "That is a Tailscale API access token (tskey-api-), which cannot add a device: in the Tailscale admin console under Settings → Keys, click \"Generate auth key\" and use the tskey-auth- kind.",
  "Tailscale 密钥应该是 tskey-auth- 开头的 Auth key。": "The Tailscale key should be an auth key starting with tskey-auth-.",
  "Tailscale 密钥应该是 tskey-auth- 开头的 Auth key（在 Tailscale 后台 Settings → Keys 里点「Generate auth key」）。": "The Tailscale key should be an auth key starting with tskey-auth- (Settings → Keys → \"Generate auth key\" in the Tailscale admin console).",
  "在 Tailscale 后台的 Settings → Keys 里点「Generate auth key」，生成一个 Auth key（tskey-auth- 开头；不是 API access token），贴在这里。配置时会顺便装好 Tailscale 并加入你的网络；密钥只用这一次，用完就从那台机器上删掉。目前只支持 Linux。": "In the Tailscale admin console under Settings → Keys, click \"Generate auth key\" (it starts with tskey-auth-; not an API access token) and paste it here. Setup then also installs Tailscale and joins your network; the key is used once and deleted from that machine afterwards. Linux only for now.",
  "同一个操作重复了，先停下了": "The same step repeated, stopped for now",
