  "把要做的事直接发给我；要动文件或系统时我会先问你。也可以让主助理把活派给我。": "Just send me what to do; I ask before touching files or the system. The main assistant can also hand work to me.",
  "把要做的事直接发给我，我自己做完。也可以让主助理把活派给我。": "Just send me what to do and I will get it done. The main assistant can also hand work to me.",
