  // --- permissions overview ----------------------------------------------
  "成本": "Cost",
  "机器人能力总览": "Bot capabilities",
  "✓ 直接做": "✓ Runs",
  "问 先问你": "Ask · asks you",
  "— 未授权": "— Not granted",
  "改审批级别会实时反映在这里；危险命令和你的规则仍可能单独拦截。": "Changing the approval level updates this table live; dangerous commands and your rules can still block separately.",
  "一键 strict：审批层面的最小权限——审批改为谨慎、生成先问、其他位置一律不许、sudo 先问、接管只看；机器人能力（工具授权）不变。改动会写进审计。": "One-tap strict: least privilege at the approval layer — level careful, generation asks, outside denied, sudo asks, takeover view-only; bot tool grants stay as they are. Written to the audit.",
  "一键 strict": "One-tap strict",
  "写文件": "Write files",
  "删文件": "Delete files",
  "发消息": "Send messages",
  "发文件": "Send files",
  "生成媒体": "Generate media",
  "切机器": "Switch machines",
  "跟随级别": "Follow the level",
  "每次先问": "Ask every time",
  "{0} 条": "{0}",
