  "机器人": "Bot",
  "问": "Ask",
  "还没有机器人": "No bots yet",
  "收紧这台机器？": "Tighten this machine?",
  "审批级别改为「谨慎」，生成图片/视频每次先问，其他位置一律不许，sudo 先问，接管桌面改为「只能看」。机器人的工具授权不变；这些改动会写进审计。": "Set the approval level to careful, ask before every generation, deny everything outside, ask for sudo, and set takeover to view-only. Bot tool grants stay; the change is written to the audit.",
  "已收紧：谨慎 · 生成先问 · 其他位置不许 · sudo 先问 · 接管只看": "Tightened: careful · generation asks · outside denied · sudo asks · takeover view-only",
  "这条审批不在了，可能已经处理过。": "That approval is gone; it may have been handled already.",
  // --- cost ---------------------------------------------------------------
  "按模型的 token 用量估算花费。单价按「每百万 tokens」填写；没设单价的模型显示「未设单价」。": "Estimates spend from each model's tokens. Enter prices per million tokens; models without a price show “no price”.",
