  "这台电脑没装 Tailscale：装好后才能开外网访问。": "Tailscale is not installed on this computer; install it to turn on public access.",
  "还差一步：去 Tailscale 后台打开 Funnel 和 HTTPS 证书，然后点「重试」。": "One more step: enable Funnel and HTTPS certificates in the Tailscale admin console, then press Retry.",
  "已开启：手机在任何网络下都能连（不用装 Tailscale）。": "On: the phone connects on any network (no Tailscale needed).",
