  "没改成：{0}": "Not changed: {0}",
  "复制失败": "Copy failed",
  "语言、主题、是否显示工具过程和时区只存在这台设备上，不会同步到别的设备。": "Language, theme, showing tool steps and the time zone live only on this device; they do not sync to other devices.",
  "返回设置列表": "Back to settings",
  "在手机飞书里直接给这台机器的助理发消息、收结果（文字、图片、视频），出门在外也能用。这台机器自己连飞书，不用公网地址。下面这个是总入口：在飞书里发「切换」按编号换人，或者消息开头写「@名字」，就能找任何一台机器上的机器人，之后的消息都发给它；发「/home」回到主助理。": "Message this machine's assistant from Feishu on your phone and get results back (text, pictures, video), wherever you are. This machine connects to Feishu itself; no public address needed. This is the main entry: in Feishu send \"切换\" to switch by number, or start a message with \"@name\" to reach a bot on any machine - later messages keep going to it; send \"/home\" to return to the main assistant.",
  "默认由哪个助手回复": "Assistant that answers by default",
  "单独的飞书机器人": "Feishu bots of their own",
  "给某个机器人单独建一个飞书应用：在飞书里它就是一个单独的联系人，发给它的消息都由它回答；把几个这样的应用拉进同一个飞书群，@ 谁就是谁回答。建应用的步骤和上面一样（权限、长连接、接收消息事件都要配）；每个应用要单独配对。": "Give one bot a Feishu app of its own: in Feishu it is a contact of its own and answers everything sent to it; put several such apps in one Feishu group and whoever is @-mentioned answers. Create the app as above (permissions, long connection, the receive-message event); each app is paired on its own.",
  "添加一个": "Add one",
  "哪个机器人": "Which bot",
  "添加并连接": "Add and connect",
  "还没有。": "None yet.",
