  "会在那个窗口里按按钮或填文字，不动你的鼠标。": "It will press buttons or fill in text in that window, without touching your mouse.",
  "Windows：在后台按按钮、填文字，不动鼠标": "Windows: press buttons and fill in text in the background, without the mouse",
  "桌面程序": "Desktop programs",
  "这台机器上机器人的桌面": "Bot desktops on this machine",
  "轻量：只有窗口，省内存": "Light: windows only, less memory",
  "完整：XFCE 桌面": "Full: the XFCE desktop",
  "每个机器人有一块自己的屏幕，开着的有 {0} 块。没人用 {1} 分钟就自动关掉，要用时再打开（浏览器的登录状态不会丢）。改了以后，新打开的桌面才生效。": "Each bot has a screen of its own; {0} open now. One nobody uses for {1} minutes is closed and opens again when needed (browser logins are kept). A change applies to desktops opened after it.",
  "已保存，新打开的桌面会用这个": "Saved; desktops opened from now on use it",
  "这台机器没装 XFCE，现在仍用轻量桌面。要完整桌面，先在这台机器上运行 sudo apt install xfce4（Rocky 等用 sudo dnf groupinstall Xfce），或者让机器人帮你装。": "XFCE is not installed on this machine, so the light desktop is still used. For the full desktop, run sudo apt install xfce4 on it first (sudo dnf groupinstall Xfce on Rocky and similar), or ask a bot to install it.",
  "每个机器人有一块自己的屏幕，开着的有 {0} 块。没人用 {1} 分钟就自动关掉，要用时再打开（浏览器的登录状态不会丢）。改了以后，新打开的桌面才生效。{2}": "Each bot has a screen of its own; {0} open now. One nobody uses for {1} minutes is closed and opens again when needed (browser logins are kept). A change applies to desktops opened after it.{2}",
  " {0}": " {0}",
  "轻量桌面：没有任务栏和图标，空着是正常的。机器人打开浏览器或程序时，窗口会出现在这里；接管后右键空白处有菜单。": "Light desktop: no taskbar or icons, so an empty screen is normal. Windows appear here when a bot opens a browser or program; after taking over, right-click the empty area for a menu.",
  "这台机器的屏幕只显示机器人的浏览器，没有桌面；空着（黑屏）是正常的，机器人打开浏览器时会铺满这里。": "This machine’s screen shows only the bot’s browser, with no desktop; an empty (black) screen is normal, and the browser fills it when a bot opens one.",
  "Tailscale 地址要手机也装 Tailscale 并登录同一个账号；局域网地址只有电脑能访问时（虚拟机内网），把虚拟机网络改成「桥接」": "A Tailscale address needs Tailscale on the phone, signed in to the same account; a LAN address only the computer can reach (a VM’s internal network) needs the VM network set to bridged",
  "主助理完全信任": "Fully trust the main assistant",
  "主助理用 sudo、动工作区以外的位置，都直接做": "The main assistant uses sudo and works outside the workspace without asking",
  "只对主助理生效，其他机器人不变。格式化磁盘、删除系统目录、关机重启这类危险命令，以及你写的「先问我」规则，仍然会问你。": "Only the main assistant; other bots are unchanged. Dangerous commands (formatting a disk, deleting system folders, shutting down or restarting) and your own \"ask me first\" rules still ask.",
  "主助理": "Main assistant",
  "完全信任": "fully trusted",
  "已打开：主助理只有危险命令还会问你": "On: the main assistant now asks only before dangerous commands",
  "已关闭：主助理的 sudo 和其他位置恢复先问": "Off: the main assistant asks again before sudo and places outside the workspace",
  "触摸板": "Touchpad",
  "直接点": "Direct",
  "触摸板：拖动移动光标，轻点是左键，双击按住可以拖动，双指轻点是右键，双指上下滑是滚动": "Touchpad: drag to move the pointer, tap to click, double-tap and hold to drag, two-finger tap for right-click, two fingers up or down to scroll",
  "直接点：点哪里就点哪里，按住拖动，长按是右键，双指上下滑是滚动": "Direct: tap where you want to click, drag to hold the button, long press for right-click, two fingers up or down to scroll",
  "这个码里带着这台机器的所有地址。用 Lamplit App 扫：和电脑在同一个局域网就走局域网，不在就自动走 Tailscale（手机上要装 Tailscale 并登录同一个账号）。": "This code carries every address of this machine. Scan it with the Lamplit app: on the same network it uses the LAN, elsewhere it switches to Tailscale by itself (the phone needs Tailscale signed in to the same account).",
  "Tailscale 装好了{0}，在外面也能连上这台机器": "Tailscale is installed{0}; this machine can be reached from anywhere",
