  "新的工作区文件夹（完整路径，{0}）。": "New workspace folder (full path, {0}).",
  "· 所有机器人都能在这里读写，别选放着重要资料的文件夹；": "· Every bot can read and write here, so do not pick a folder with important files;",
  "· 原来工作区里的文件不会自动搬过去，需要的话自己复制；": "· Files in the old workspace are not moved; copy them over yourself if you need them;",
  "· 换完 Lamplit 会重启几秒钟。": "· Lamplit restarts for a few seconds after the change.",
