  "adb 在哪（Android platform-tools 里的 adb.exe）": "Where adb is (adb.exe in Android platform-tools)",
  "手机屏幕": "Phone screen",
  "例如 C:\\Android\\platform-tools\\adb.exe": "e.g. C:\\Android\\platform-tools\\adb.exe",
