  "连在这台电脑上的安卓手机：看屏幕、点、输入、打开 App": "The Android phone on this computer: see the screen, tap, type, open apps",
  "想在你的手机上做一步": "Wants to do a step on your phone",
  "会在手机上点、滑或输入；付款、发送、发布、删除每次都会先问你。手机锁着时不会去解锁。": "It taps, swipes or types on the phone; paying, sending, publishing and deleting always ask you first. It never unlocks a locked phone.",
  "这台电脑上还没找到 adb。装好 Android platform-tools，或在下面填 adb.exe 的位置。": "adb was not found on this computer. Install Android platform-tools, or enter where adb.exe is below.",
  "这台机器上没有 adb，手机要连在装了 adb 的电脑上。": "This machine has no adb; connect the phone to a computer that has it.",
  "没有连着的手机。插上数据线，打开 USB 调试，在手机上点「允许」。": "No phone connected. Plug in the cable, turn on USB debugging and tap Allow on the phone.",
  "还没允许这台电脑：解锁手机，在弹窗里点「允许」": "Not allowed yet: unlock the phone and tap Allow in the prompt",
  "状态：{0}": "State: {0}",
  "已连接 · 锁着屏（机器人会请你解锁）": "Connected · locked (bots will ask you to unlock)",
