  "已经重新开始跑了：需要你点头的那一步会在这里弹出来。": "Running again: the step that needs your OK will pop up here.",
  "找不到这个定时任务了。": "That routine is gone.",
  "定时任务「{0}」": "Routine \"{0}\"",
  "没有变化": "Nothing new",
  "看指令": "Show instruction",
  "改指令": "Edit instruction",
  "指令已更新，下次运行按新的来": "Instruction saved; the next run uses it",
  "恢复": "Resume",
  "已恢复，按计划继续跑": "Resumed; it runs on schedule again",
  "已暂停，不会再自动跑": "Paused; it won't run on its own",
  "现在再跑一次": "Run once more now",
  "使用文档": "Documentation",
  "息屏后系统会让 Lamplit 休眠，机器就连不上这部手机了。点下面的按钮，在弹出的对话框里选「允许」，让它在后台一直运行。": "With the screen off, the system puts Lamplit to sleep and your machines lose this phone. Tap the button below and choose Allow so it keeps running in the background.",
  "这个牌子的手机还要在「应用信息 → 耗电管理（或电池）」里打开「允许后台运行」和「允许自启动」。": "On this brand of phone, also turn on Allow background activity and Auto-launch under App info → Battery.",
  "允许在后台一直运行": "Keep running in the background",
  "打开应用信息": "Open app info",
  "在「耗电管理」或「电池」里打开「允许后台运行」和「允许自启动」，再回来": "Under Battery, turn on Allow background activity and Auto-launch, then come back",
