  "删除「{0}」？": "Delete \"{0}\"?",
  "它的对话记录和记忆会收进归档，不再出现；它等你确认的卡片会收起，定时任务会暂停。": "Its chat and memory go to an archive and no longer show; its cards waiting for you close and its scheduled tasks pause.",
