  "可以写：每天 9:00、工作日 8:30、每周五 18:00、每月 1 号 10:00、每 30 分钟。": "For example: 每天 9:00 (daily), 工作日 8:30 (weekdays), 每周五 18:00 (Fridays), 每月 1 号 10:00 (monthly), 每 30 分钟 (every 30 minutes), or a cron line.",
  "时间改好了": "Time changed",
