  "交给「{0}」了；要它接着跑，点「启用」。": "Given to \"{0}\"; click Enable to have it run again.",
  "已收起": "Dismissed",
  "连接正常 · {0} 毫秒{1}{2}": "Connected · {0} ms{1}{2}",
  "这个助手专属 {0}": "This assistant's own {0}",
  "助手和浏览器都在这台电脑上": "Assistants and the browser are on this computer",
  "只是从列表里拿掉，那台机器上的助手和数据不会删除；以后可以重新添加。": "This only takes it off the list; the assistants and data on that machine are not deleted, and you can add it again later.",
  "（危险操作和工作区外的改动照样会问）": " (dangerous steps and changes outside the workspace still ask)",
  "「以后都允许」：以后{0}都不再问{1}。{2}": "\"Always allow\": from now on, {0} no longer asks{1}. {2}",
