  "这条命令只是查看，不会改动任何东西。": "This command only looks; it changes nothing.",
  "在这台电脑上运行命令前，都先问你一次": "It asks you before running any command on this computer",
  "允许这 {0} 条": "Allow these {0}",
  "这几条都会运行，不再一条条问": "All of them run, without asking one by one",
  "允许后这几条都会运行；这一轮后面只是查看的命令也不再问你，会改动东西的照样先问。": "Once allowed, all of these run; later commands in this turn that only look are not asked about either. Anything that changes things still asks first.",
  "允许后，这一轮后面只是查看的命令不再问你；会改动东西的照样先问。": "Once allowed, later commands in this turn that only look are not asked about. Anything that changes things still asks first.",
