  "这台电脑上有 1 个，在对话里：": "1 on this computer, in its chat:",
  "这台电脑上有 {0} 个，在各自的对话里：": "{0} on this computer, in their chats:",
  "去看看": "Take a look",
  "连不上：{0}。那边如果有等你的事，连上后会出现在这里。": "Can't reach: {0}. Anything waiting for you there will show up here once it's reachable.",
  "没有等你确认的事了。": "Nothing is waiting for you.",
  "它在等你回一句话，点开看看": "It's waiting for a reply from you; open to see",
  "已删除的助手": "A deleted assistant",
  "不想自己选？直接对「{0}」说：「拉个群，你和{1}一起做…」，它会替你建好。": "Rather not pick? Just tell \"{0}\": \"Make a group where you and {1} work on…\" and it sets it up for you.",
  "现在只有「{0}」一位助手，群里至少要两位。想要别的帮手，直接对它说「帮我新建一个写文案的助手」，它会替你建好。": "\"{0}\" is your only assistant, and a group needs two. Want another helper? Tell it \"Make me an assistant for writing copy\" and it sets one up.",
  "有什么事直接跟「{0}」说就行。想要别的帮手，也跟它说一声，它会替你建好。": "Just tell \"{0}\" what you need. Want another helper? Ask it, and it sets one up for you.",
  "需要你回复一下：": "Needs your reply: ",
  "你允许了{0}的这一步": "You allowed a step of {0}",
  "现在跑一次": "Run it now",
  "你让{0}的定时任务再跑一次": "You had {0} run its routine again",
