  "{0}/{1} · {2}": "{0}/{1} · {2}",
  "应用重启时这一轮被打断了，没有做完，也不会自动重做。已经写好的文件都还在工作区里；需要的话再跟我说一次。如果它当时在等你批准，那张卡片还在「动态」里。": "The app restarted in the middle of this turn, so it did not finish and will not start again by itself. Files already written are still in the workspace; tell me again if you still want it. If it was waiting for your OK, that card is still there.",
  "应用重启时这一轮被打断了。群里的任务板会在半分钟内自动接着做，已经写好的文件都还在。": "The app restarted in the middle of this turn. The group's task board goes on by itself within half a minute; files already written are still there.",
