  "想发{0}": "Wants to send {0}",
  "下面是草稿，可以直接改。点「发送」才会发出去，发出去的就是框里的字。": "Below is the draft; edit it right here. Nothing goes out until you press Send, and what goes out is the text in the boxes.",
  "想改「{0}」{1}的{2}": "Wants to change the {2} of “{0}”{1}",
  "规则": "rules",
  "同意后马上生效。之后可以在对话里点「撤销」改回去。": "Takes effect as soon as you agree. You can change it back later with Undo in the chat.",
