  "用你自己的 X 开发者应用，助手发的每一条都先给你看草稿": "With your own X developer app; every post an assistant writes is shown to you as a draft first",
  "1. 在 X 开发者后台（{0}）打开你的应用 → 「User authentication settings」：类型选「Web App」，权限选「Read and write」，回调地址填下面这一行。": "1. In the X developer portal ({0}) open your app → “User authentication settings”: type “Web App”, permissions “Read and write”, and paste the line below as the callback URL.",
  "回调地址": "Callback URL",
  "2. 在应用的「Keys and tokens」里复制「OAuth 2.0 Client ID」和「Client Secret」，填在这里。它们加密存在这台电脑上，不进聊天，也不会发给别的机器。": "2. Copy the “OAuth 2.0 Client ID” and “Client Secret” from the app's “Keys and tokens” into here. They are kept encrypted on this computer, never in a chat and never sent to another machine.",
  "X 的 Client ID": "X Client ID",
