  "在 X 自己的网页上登录并点「允许」。Lamplit 看不到你的 X 密码": "Sign in on X's own page and press Allow. Lamplit never sees your X password",
  "在打开的 X 页面上登录并点「允许」，完成后回到这里": "Sign in on the X page that opened and press Allow, then come back here",
